/**
 * Token-2022 TransferFee: compute the fee WITHHELD on a single transfer.
 *
 * Mirrors the on-chain `calculate_fee`:
 *   fee = 0                                   if basisPoints == 0 or amount == 0
 *   fee = min( ceil(amount * bps / 10000), maximumFee )   otherwise
 *
 * Ceiling division is done as (numerator + 9999) / 10000 on bigints.
 *
 * @param amount        pre-fee transfer amount, in base units (bigint)
 * @param basisPoints   transfer_fee_basis_points (0..=10000)
 * @param maximumFee    hard cap on the withheld fee, in base units (bigint)
 * @returns             the fee withheld on the recipient account (bigint)
 */
function transferFee(
  amount: bigint,
  basisPoints: number,
  maximumFee: bigint,
): bigint {
  if (basisPoints === 0 || amount === 0n) return 0n;
  const numerator = amount * BigInt(basisPoints);
  const raw = (numerator + 9999n) / 10000n; // ceiling division
  return raw < maximumFee ? raw : maximumFee;
}

/// The decision core of a Token-2022 transfer hook's `Execute` handler.
///
/// On every SPROUT transfer, the runtime CPIs into your hook with the transfer
/// `amount` plus the resolved extra accounts. Your hook reads its own state and
/// decides: let the transfer proceed, or return an error so the whole transfer
/// reverts. It CANNOT move funds itself (the transfer accounts arrive read-only,
/// non-signer); its only power is to pass or fail.
///
/// Return value convention (so the grader can compare a single value):
///   allowed  -> the transferred `amount` cast to i64
///   rejected -> a negative error code (`-1` allowlist, `-2` paused)
fn hook_execute(destination_allowed: bool, is_paused: bool, amount: u64) -> i64 {
    // Pause is the global kill-switch: it beats the allowlist.
    if is_paused {
        return -2;
    }
    // The hook's only real power on the transfer path: refuse.
    if !destination_allowed {
        return -1;
    }
    amount as i64
}

